        if(names[i][0] === "M") {
            march[0]++;
        }

        if(names[i][0] === "A") {
            march[1]++;
        }

        if(names[i][0] === "R") {
            march[2]++;
        }

        if(names[i][0] === "C") {
            march[3]++;
        }

        if(names[i][0] === "H") {
            march[4]++;
        }
